use hec_native_ic::jac::{Curve,Div};
use crate::{linear::{Sparse,put},prepared::Prepared,table_oracle::{split,OracleStats}};
pub fn rows(c:&Curve,d:&Div,t:&Div,m:usize,fb:&[(u64,u64)],index:&[usize],ell:u64,audit:bool,prep:&Prepared)->(Vec<Option<(Sparse,u64)>>,usize){let f=hec_native_ic::fp::Fp::new(ell);let mut rows=vec![];let mut nonsplit=0;for(which,r)in[d,t].into_iter().enumerate(){let Some(roots)=split(&r.u,&c.fp,&mut OracleStats::default(),&prep.roots)else{nonsplit+=1;continue;};let mut row=Sparse::new();let mut native=c.zero();for &(x,mult)in roots.as_slice(){let j=index[x as usize];assert_ne!(j,usize::MAX);let y=r.v.eval(x,&c.fp);let sign=if y==fb[j].1{1}else{assert_eq!(y,c.fp.neg(fb[j].1));-1};let col=if j<m{j}else{j+1};put(&mut row,col,f.from_i64(sign*mult as i64),&f);if audit{for _ in 0..mult{native=c.add_place(&native,x,y);}}}if audit{assert_eq!(native,*r,"public Mumford decomposition");}let rhs=if which==0{1}else{put(&mut row,m,f.neg(1),&f);0};rows.push(Some((row,rhs)));}(rows,nonsplit)}
